'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "name": "dataset"
  },
  "width": 523.0,
  "height": 148,
  "transform": [
    {
      "window": [
        {
          "op": "row_number",
          "as": "k"
        }
      ],
      "groupby": [
        "Process Phase"
      ],
      "sort": [
        {
          "field": "Week Starting"
        }
      ]
    },
    {
      "calculate": "datum[''Process Phase''] == ''Before automation'' ? datum.k - 1 : datum.k + 8",
      "as": "pos"
    },
    {
      "calculate": "timeFormat(toDate(datum[''Week Starting'']), ''%-d %b'')",
      "as": "wk"
    }
  ],
  "layer": [
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "count",
              "as": "n"
            }
          ]
        }
      ],
      "mark": {
        "type": "rect",
        "color": "#EEF0F6",
        "cornerRadius": 4
      },
      "encoding": {
        "x": {
          "datum": 7.45,
          "type": "quantitative",
          "axis": null
        },
        "x2": {
          "datum": 8.55
        },
        "y": {
          "datum": 0,
          "type": "quantitative",
          "axis": {
            "values": [
              0,
              100,
              200,
              300
            ]
          }
        },
        "y2": {
          "datum": 300
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "count",
              "as": "n"
            }
          ]
        }
      ],
      "mark": {
        "type": "text",
        "fontSize": 9.5,
        "color": "#667085",
        "lineBreak": "|",
        "baseline": "bottom",
        "dy": -20
      },
      "encoding": {
        "x": {
          "datum": 8,
          "type": "quantitative",
          "axis": null
        },
        "y": {
          "datum": 0,
          "type": "quantitative",
          "axis": {
            "values": [
              0,
              100,
              200,
              300
            ]
          }
        },
        "text": {
          "value": "automation|built"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum[''Process Phase''] == ''Before automation''"
        }
      ],
      "mark": {
        "type": "area",
        "color": {
          "x1": 1,
          "y1": 1,
          "x2": 1,
          "y2": 0,
          "gradient": "linear",
          "stops": [
            {
              "offset": 0,
              "color": "rgba(235,104,52,0.02)"
            },
            {
              "offset": 1,
              "color": "rgba(235,104,52,0.3)"
            }
          ]
        }
      },
      "encoding": {
        "x": {
          "field": "pos",
          "type": "quantitative",
          "title": null,
          "axis": null,
          "scale": {
            "domain": [
              -0.4,
              16.4
            ],
            "nice": false,
            "zero": false
          }
        },
        "y": {
          "field": "Average Weekly Reporting Minutes",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              300
            ]
          },
          "axis": {
            "values": [
              0,
              100,
              200,
              300
            ]
          }
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum[''Process Phase''] == ''After automation''"
        }
      ],
      "mark": {
        "type": "area",
        "color": {
          "x1": 1,
          "y1": 1,
          "x2": 1,
          "y2": 0,
          "gradient": "linear",
          "stops": [
            {
              "offset": 0,
              "color": "rgba(27,175,122,0.02)"
            },
            {
              "offset": 1,
              "color": "rgba(27,175,122,0.3)"
            }
          ]
        }
      },
      "encoding": {
        "x": {
          "field": "pos",
          "type": "quantitative",
          "title": null,
          "axis": null,
          "scale": {
            "domain": [
              -0.4,
              16.4
            ],
            "nice": false,
            "zero": false
          }
        },
        "y": {
          "field": "Average Weekly Reporting Minutes",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              300
            ]
          },
          "axis": {
            "values": [
              0,
              100,
              200,
              300
            ]
          }
        }
      }
    },
    {
      "mark": {
        "type": "line",
        "strokeWidth": 2.2
      },
      "encoding": {
        "x": {
          "field": "pos",
          "type": "quantitative",
          "title": null,
          "axis": null,
          "scale": {
            "domain": [
              -0.4,
              16.4
            ],
            "nice": false,
            "zero": false
          }
        },
        "y": {
          "field": "Average Weekly Reporting Minutes",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              300
            ]
          },
          "axis": {
            "values": [
              0,
              100,
              200,
              300
            ]
          }
        },
        "color": {
          "field": "Process Phase",
          "type": "nominal",
          "scale": {
            "domain": [
              "Before automation",
              "After automation"
            ],
            "range": [
              "#EB6834",
              "#1BAF7A"
            ]
          },
          "legend": {
            "orient": "bottom",
            "direction": "horizontal",
            "title": null,
            "symbolType": "square",
            "symbolSize": 90,
            "labelFontSize": 10.5,
            "labelColor": "#344054",
            "labelLimit": 320,
            "columnPadding": 22,
            "offset": 26,
            "labelExpr": "datum.label == ''Before automation'' ? ''Before automation (Jan\u2013Feb 2023)'' : datum.label == ''After automation'' ? ''After automation (May\u2013Jul 2023)'' : datum.label"
          }
        }
      }
    },
    {
      "mark": {
        "type": "point",
        "filled": true,
        "size": 40,
        "stroke": "white",
        "strokeWidth": 1.2,
        "opacity": 1
      },
      "encoding": {
        "x": {
          "field": "pos",
          "type": "quantitative",
          "title": null,
          "axis": null,
          "scale": {
            "domain": [
              -0.4,
              16.4
            ],
            "nice": false,
            "zero": false
          }
        },
        "y": {
          "field": "Average Weekly Reporting Minutes",
          "type": "quantitative",
          "title": null,
          "scale": {
            "domain": [
              0,
              300
            ]
          },
          "axis": {
            "values": [
