              200,
              300
            ]
          }
        },
        "color": {
          "field": "Process Phase",
          "type": "nominal",
          "scale": {
            "domain": [
              "Before automation",
              "After automation"
            ],
            "range": [
              "#EB6834",
              "#1BAF7A"
            ]
          },
          "legend": {
            "orient": "bottom",
            "direction": "horizontal",
            "title": null,
            "symbolType": "square",
            "symbolSize": 90,
            "labelFontSize": 10.5,
            "labelColor": "#344054",
            "labelLimit": 320,
            "columnPadding": 22,
            "offset": 26,
            "labelExpr": "datum.label == ''Before automation'' ? ''Before automation (Jan\u2013Feb 2023)'' : datum.label == ''After automation'' ? ''After automation (May\u2013Jul 2023)'' : datum.label"
          }
        },
        "tooltip": [
          {
            "field": "Week Starting",
            "type": "temporal",
            "format": "%-d %b %Y"
          },
          {
            "field": "Average Weekly Reporting Minutes",
            "title": "Minutes",
            "format": ".0f"
          }
        ]
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "mean",
              "field": "Average Weekly Reporting Minutes",
              "as": "avg"
            },
            {
              "op": "min",
              "field": "pos",
              "as": "a"
            },
            {
              "op": "max",
              "field": "pos",
              "as": "b"
            }
          ],
          "groupby": [
            "Process Phase"
          ]
        }
      ],
      "mark": {
        "type": "rule",
        "strokeDash": [
          5,
          4
        ],
        "strokeWidth": 1.4
      },
      "encoding": {
        "x": {
          "field": "a",
          "type": "quantitative",
          "axis": null
        },
        "x2": {
          "field": "b"
        },
        "y": {
          "field": "avg",
          "type": "quantitative",
          "axis": {
            "values": [
              0,
              100,
              200,
              300
            ]
          }
        },
        "color": {
          "field": "Process Phase",
          "type": "nominal",
          "scale": {
            "domain": [
              "Before automation",
              "After automation"
            ],
            "range": [
              "#EB6834",
              "#1BAF7A"
            ]
          },
          "legend": {
            "orient": "bottom",
            "direction": "horizontal",
            "title": null,
            "symbolType": "square",
            "symbolSize": 90,
            "labelFontSize": 10.5,
            "labelColor": "#344054",
            "labelLimit": 320,
            "columnPadding": 22,
            "offset": 26,
            "labelExpr": "datum.label == ''Before automation'' ? ''Before automation (Jan\u2013Feb 2023)'' : datum.label == ''After automation'' ? ''After automation (May\u2013Jul 2023)'' : datum.label"
          }
        }
      }
    },
    {
      "transform": [
        {
          "aggregate": [
            {
              "op": "mean",
              "field": "Average Weekly Reporting Minutes",
              "as": "avg"
            },
            {
              "op": "min",
              "field": "pos",
              "as": "a"
            },
            {
              "op": "max",
              "field": "pos",
              "as": "b"
            }
          ],
          "groupby": [
            "Process Phase"
          ]
        },
        {
          "calculate": "''avg '' + format(datum.avg, datum.avg > 100 ? ''.0f'' : ''.1f'')",
          "as": "lab"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 10,
        "dy": -7,
        "fontSize": 11.5,
        "fontWeight": 600,
        "color": "#101828"
      },
      "encoding": {
        "x": {
          "field": "b",
          "type": "quantitative",
          "axis": null
        },
        "y": {
          "field": "avg",
          "type": "quantitative",
          "axis": {
            "values": [
              0,
              100,
              200,
              300
            ]
          }
        },
        "text": {
          "field": "lab"
        }
      }
    },
    {
      "transform": [
        {
          "filter": "datum.k == 1 || datum.k == 4 || datum.k == 8"
        }
      ],
      "mark": {
        "type": "text",
        "baseline": "top",
        "dy": 7,
        "fontSize": 10,
        "color": "#667085"
      },
      "encoding": {
        "x": {
          "field": "pos",
          "type": "quantitative",
          "title": null,
          "axis": null,
          "scale": {
            "domain": [
              -0.4,
              16.4
            ],
            "nice": false,
            "zero": false
          }
        },
        "y": {
          "datum": 0,
          "type": "quantitative",
          "axis": {
            "values": [
              0,
              100,
              200,
              300
            ]
          }
        },
        "text": {
          "field": "wk"
        }
      }
    }
  ],
  "autosize": {
    "type": "pad"
  }
}'

